// Le rattrapage rate en SILENCE : il rend honores 0 et l'execution reste
// verte. Un paiement bloque, c'est un marchand qui a peut-etre paye sans
// recevoir son acces — le pire etat possible, et celui que personne ne
// regarde. Lever ici declenche « Alerte Erreurs » par settings.errorWorkflow.
//
// LE MESSAGE N'A NI DEUX-POINTS NI RETOUR A LA LIGNE. n8n scinde le texte
// d'une Error sur ces caracteres, et l'alerte n'en recevrait qu'un fragment.
const r = $input.first().json || {};
const bloques = Number(r.bloques || 0);

if (bloques > 0) {
  const refs = (r.detailBloques || [])
    .map((b) => `${b.reference} (${b.etat}, ${b.heures}h)`)
    .join(' — ');
  throw new Error(
    `${bloques} paiement(s) bloque(s) depuis plus de ${r.seuilAlerteH}h — ${refs}`,
  );
}

return [{ json: { examines: r.examines, honores: r.honores, bloques: 0 } }];
